tool_calls.arguments:
{"command":"cd /workspace && kubectl patch ds app -n default --type=strategic -p '{
  "spec": {
    "template": {
      "spec": {
        "tolerations": [
          {"key":"benchmark","operator":"Equal","value":"daemonset","effect":"NoSchedule"}
        ]
      }
    }
  }
}' 2>&1; echo "--- ds status ---"; kubectl get ds app -n default -o jsonpath='{.status.desiredNumberScheduled} {.status.currentNumberScheduled} {.status.numberReady} {.status.numberMisscheduled}{"\n"}{.metadata.generation} {.status.observedGeneration}{"\n"}' 2>&1"}

